"""chunking 单元测试：分带覆盖性/预算约束、帧分组推导、内存探测。"""
import pytest

from vdenoise import chunking


class TestPlanBands:
    def test_single_band_when_fits(self):
        assert chunking.plan_bands(100, 2, 1920, 10 ** 9) == [(0, 100)]

    def test_bands_cover_exactly(self):
        bands = chunking.plan_bands(97, 3, 1000, 20000)
        assert len(bands) > 1
        assert bands[0][0] == 0
        assert bands[-1][1] == 97
        for (s0, e0), (s1, e1) in zip(bands, bands[1:]):
            assert e0 == s1, "分带必须无缝衔接"
            assert e0 > s0, "空带不允许出现"

    def test_budget_respected(self):
        # 每带 (核心高 + 2r) 行 * 行字节 * 代价系数 <= 预算（核心高>1 时）
        budget = 50000
        r = 3
        row = 1000
        bands = chunking.plan_bands(200, r, row, budget, cost_factor=6.0)
        for s, e in bands:
            ctx_rows = (e - s) + 2 * r
            if e - s > 1:
                assert ctx_rows * row * 6.0 <= budget * 1.5  # 末带可能更短，留容差

    def test_tiny_budget_still_progresses(self):
        # 预算极小也必须给出核心高 >= 1 的方案，保证能推进
        bands = chunking.plan_bands(10, 2, 10 ** 6, 1)
        assert bands == [(i, i + 1) for i in range(10)]

    def test_invalid_args(self):
        with pytest.raises(ValueError):
            chunking.plan_bands(0, 1, 100, 1000)
        with pytest.raises(ValueError):
            chunking.plan_bands(10, -1, 100, 1000)


class TestPlanFramesPerChunk:
    def test_basic(self):
        # 预算 1000，帧 100 字节 → 1000 // 200 = 5
        assert chunking.plan_frames_per_chunk(100, 1000) == 5

    def test_min_clamp(self):
        assert chunking.plan_frames_per_chunk(10 ** 9, 100) == 1

    def test_max_clamp(self):
        assert chunking.plan_frames_per_chunk(1, 10 ** 12) == chunking.MAX_CHUNK_FRAMES

    def test_invalid(self):
        with pytest.raises(ValueError):
            chunking.plan_frames_per_chunk(0, 1000)


class TestMemoryProbe:
    def test_available_memory_positive(self):
        assert chunking.available_memory_bytes() > 0

    def test_default_budget_fraction(self):
        budget = chunking.default_budget()
        avail = chunking.available_memory_bytes()
        assert 0 < budget <= avail

